//! Blocks the composer offers: built-in ones shipped with the app
//! (`catalog/builtin/*.md`) and the skills and subagents in the user's library.

use std::collections::BTreeMap;
use std::path::Path;

use serde::{Deserialize, Serialize};

use crate::claude_config::frontmatter;
use crate::library::{ItemKind, LibraryItem, ops};

/// `(file stem, text)` for every built-in block, generated by build.rs.
const BUILTIN: &[(&str, &str)] = include!(concat!(env!("OUT_DIR"), "/builtin_blocks.rs"));

/// `(source folder, file stem, text)` for every bundled third-party block.
const EXTERNAL: &[(&str, &str, &str)] = include!(concat!(env!("OUT_DIR"), "/external_blocks.rs"));

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum BlockKind {
    /// Always-on guidance for CLAUDE.md.
    Instruction,
    /// A `.claude/rules` file, optionally limited to `paths`.
    Rule,
    Skill,
    Agent,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum Source {
    Builtin,
    Library,
    /// A third-party block bundled with the app (see THIRD_PARTY_NOTICES.md).
    External,
}

/// Where a third-party block comes from, kept with everything written from it.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Origin {
    pub repo: String,
    pub commit: String,
    pub path: String,
    /// SPDX id.
    pub license: String,
    pub copyright: String,
}

impl Origin {
    pub fn url(&self) -> String {
        format!(
            "https://github.com/{}/blob/{}/{}",
            self.repo, self.commit, self.path
        )
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct BlockText {
    pub title: String,
    pub summary: String,
    pub category: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub detail: Option<String>,
}

#[derive(Clone, Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Block {
    /// `builtin:<stem>`, `library:skill:<id>` or `library:agent:<id>`.
    pub id: String,
    pub kind: BlockKind,
    /// Display name and one-line summary (Korean UI text).
    pub title: String,
    pub summary: String,
    pub category: String,
    /// A few sentences on what the block makes Claude do, shown when the
    /// block is opened (`detail` / `detail_en` frontmatter).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub detail: Option<String>,
    /// The same in English (`title_en`, `summary_en`, `category_en`
    /// frontmatter); the frontend picks by language.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub en: Option<BlockText>,
    pub source: Source,
    /// File or folder name the block is written under, and the Claude Code
    /// name of a skill or subagent.
    pub name: String,
    /// `description` frontmatter for skills and subagents.
    pub description: Option<String>,
    /// Globs a rule is limited to.
    pub paths: Vec<String>,
    pub tools: Option<String>,
    pub model: Option<String>,
    pub body: String,
    /// Files next to a library skill's SKILL.md, which the composer does not copy.
    pub extra_files: usize,
    pub origin: Option<Origin>,
    /// Library items: the original frontmatter, written unchanged so fields
    /// the composer does not model (allowed-tools, permissionMode, ...) and the
    /// item's own `name` survive.
    #[serde(skip)]
    pub frontmatter: Option<String>,
}

impl Block {
    /// The title in the UI language (the Korean one when there is no English).
    pub fn display_title(&self) -> &str {
        match &self.en {
            Some(en) if crate::i18n::english() => &en.title,
            _ => &self.title,
        }
    }
}

/// Byte offset where the body starts (after the closing `---`), or `None`
/// without frontmatter. Expects LF line endings and no BOM.
fn body_start(text: &str) -> Option<usize> {
    frontmatter::parse(text)?;
    let mut offset = 0;
    let mut fences = 0;
    for line in text.split_inclusive('\n') {
        offset += line.len();
        if line.trim_end() == "---" {
            fences += 1;
            if fences == 2 {
                return Some(offset);
            }
        }
    }
    None
}

/// LF line endings and no BOM, so text from a Windows checkout or editor
/// compares and hashes the same as anywhere else.
pub fn normalize(text: &str) -> String {
    text.strip_prefix('\u{feff}')
        .unwrap_or(text)
        .replace("\r\n", "\n")
}

/// Splits a Markdown file into its frontmatter fields and body (LF endings).
pub fn split(text: &str) -> (BTreeMap<String, String>, String) {
    let text = normalize(text);
    match body_start(&text) {
        Some(start) => (
            frontmatter::parse(&text).unwrap_or_default(),
            text[start..].trim_start_matches('\n').to_string(),
        ),
        None => (BTreeMap::new(), text),
    }
}

/// The frontmatter lines between the `---` fences, as written.
fn raw_frontmatter(text: &str) -> Option<String> {
    let text = normalize(text);
    let start = body_start(&text)?;
    let inner = text[..start].trim_end().strip_suffix("---")?;
    let inner = inner.strip_prefix("---\n")?;
    Some(inner.trim_end().to_string())
}

/// Splits a joined frontmatter list on ", " outside braces, so globs such as
/// `src/**/*.{ts,tsx}` stay whole.
fn list(value: Option<&String>) -> Vec<String> {
    let Some(value) = value else {
        return Vec::new();
    };
    let mut items = Vec::new();
    let mut depth = 0usize;
    let mut current = String::new();
    let mut chars = value.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '{' => depth += 1,
            '}' => depth = depth.saturating_sub(1),
            ',' if depth == 0 && chars.peek() == Some(&' ') => {
                chars.next();
                items.push(std::mem::take(&mut current));
                continue;
            }
            _ => {}
        }
        current.push(c);
    }
    items.push(current);
    items
        .into_iter()
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .collect()
}

fn parse_builtin(stem: &str, text: &str) -> Option<Block> {
    parse_bundled(&format!("builtin:{stem}"), stem, text, Source::Builtin)
}

pub(super) fn parse_external(source: &str, stem: &str, text: &str) -> Option<Block> {
    let mut block = parse_bundled(
        &format!("external:{source}/{stem}"),
        stem,
        text,
        Source::External,
    )?;
    let (fm, _) = split(text);
    let field = |key: &str| fm.get(key).cloned().filter(|v| !v.is_empty());
    // Provenance is required; a block without it is never offered.
    block.origin = Some(Origin {
        repo: field("source_repo")?,
        commit: field("source_commit")?,
        path: field("source_path")?,
        license: field("license")?,
        copyright: field("copyright")?,
    });
    Some(block)
}

fn parse_bundled(id: &str, stem: &str, text: &str, source: Source) -> Option<Block> {
    let (fm, body) = split(text);
    let kind = match fm.get("kind")?.as_str() {
        "instruction" => BlockKind::Instruction,
        "rule" => BlockKind::Rule,
        "skill" => BlockKind::Skill,
        "agent" => BlockKind::Agent,
        _ => return None,
    };
    Some(Block {
        id: id.to_string(),
        kind,
        title: fm.get("title").cloned().unwrap_or_else(|| stem.to_string()),
        summary: fm.get("summary").cloned().unwrap_or_default(),
        category: fm.get("category").cloned().unwrap_or_default(),
        detail: fm.get("detail").cloned(),
        en: fm.get("title_en").map(|title| BlockText {
            title: title.clone(),
            summary: fm.get("summary_en").cloned().unwrap_or_default(),
            category: fm.get("category_en").cloned().unwrap_or_default(),
            detail: fm.get("detail_en").cloned(),
        }),
        source,
        name: fm.get("name").cloned().unwrap_or_else(|| stem.to_string()),
        description: fm.get("description").cloned(),
        paths: list(fm.get("paths")),
        tools: fm.get("tools").cloned(),
        model: fm.get("model").cloned(),
        body: body.trim_end().to_string(),
        extra_files: 0,
        origin: None,
        frontmatter: None,
    })
}

pub fn builtin() -> Vec<Block> {
    BUILTIN
        .iter()
        .filter_map(|(stem, text)| parse_builtin(stem, text))
        .collect()
}

/// The bundled third-party blocks as `(source folder, file stem, text)`.
pub(super) fn bundled_external() -> &'static [(&'static str, &'static str, &'static str)] {
    EXTERNAL
}

/// Path of a refreshed copy of a bundled block in the cache folder.
pub(super) fn cache_path(cache: &Path, source: &str, stem: &str) -> std::path::PathBuf {
    cache.join(source).join(format!("{stem}.md"))
}

/// Third-party blocks, preferring a newer copy fetched by "최신 받아오기".
/// A cached copy is used only if it still points at the same upstream file.
pub fn external(cache: Option<&Path>) -> Vec<Block> {
    EXTERNAL
        .iter()
        .filter_map(|(source, stem, text)| {
            let bundled = parse_external(source, stem, text)?;
            let cached = cache
                .and_then(|dir| std::fs::read_to_string(cache_path(dir, source, stem)).ok())
                .and_then(|t| parse_external(source, stem, &t))
                .filter(|c| same_upstream(c, &bundled));
            // Titles, summaries and categories are the app's own text: always
            // the bundled ones, also for copies cached by an older version.
            Some(match cached {
                Some(cached) => Block {
                    title: bundled.title,
                    summary: bundled.summary,
                    category: bundled.category,
                    detail: bundled.detail,
                    en: bundled.en,
                    ..cached
                },
                None => bundled,
            })
        })
        .collect()
}

fn same_upstream(a: &Block, b: &Block) -> bool {
    match (&a.origin, &b.origin) {
        (Some(a), Some(b)) => a.repo == b.repo && a.path == b.path && a.license == b.license,
        _ => false,
    }
}

/// The first sentence of `text` (up to `. `, `.\n` or a line break), or all
/// of it when it has one sentence.
pub(crate) fn first_sentence(text: &str) -> String {
    let text = text.trim();
    let end = text
        .char_indices()
        .find(|&(i, c)| c == '\n' || (c == '.' && text[i + 1..].starts_with([' ', '\n'])))
        .map(|(i, c)| if c == '.' { i + 1 } else { i });
    match end {
        Some(i) => text[..i].trim().to_string(),
        None => text.to_string(),
    }
}

/// A library skill or subagent as a block. Unreadable files are skipped.
fn from_library(item: &LibraryItem) -> Option<Block> {
    let path = Path::new(&item.path);
    let text = String::from_utf8_lossy(&std::fs::read(path).ok()?).into_owned();
    let (fm, body) = split(&text);
    let (kind, prefix) = match item.kind {
        ItemKind::Skill => (BlockKind::Skill, "skill"),
        ItemKind::Agent => (BlockKind::Agent, "agent"),
    };
    let extra_files = match item.kind {
        ItemKind::Skill => path
            .parent()
            .and_then(|dir| ops::file_count(dir).ok())
            .map_or(0, |n| n.saturating_sub(1)),
        ItemKind::Agent => 0,
    };
    // A long description reads as one line; the whole of it is the detail.
    let description = item.description.clone().unwrap_or_default();
    let summary = first_sentence(&description);
    let detail = (summary != description.trim()).then(|| description.trim().to_string());
    Some(Block {
        id: format!("library:{prefix}:{}", item.id),
        kind,
        title: item.name.clone(),
        summary: summary.clone(),
        category: "내 라이브러리".into(),
        detail: detail.clone(),
        en: Some(BlockText {
            title: item.name.clone(),
            summary,
            category: "My library".into(),
            detail,
        }),
        source: Source::Library,
        // The folder or file name: where the copy is written. Its frontmatter,
        // including the item's own `name`, is kept as is.
        name: item.id.clone(),
        description: item.description.clone(),
        paths: Vec::new(),
        tools: fm.get("tools").cloned(),
        model: fm.get("model").cloned(),
        body: body.trim_end().to_string(),
        extra_files,
        origin: None,
        frontmatter: raw_frontmatter(&text),
    })
}

pub fn all(library_items: &[LibraryItem], cache: Option<&Path>) -> Vec<Block> {
    let mut blocks = builtin();
    blocks.extend(external(cache));
    blocks.extend(library_items.iter().filter_map(from_library));
    blocks
}

#[cfg(test)]
mod tests {
    use super::*;

    /// English title, summary and category, with the same English category
    /// for every use of a Korean one.
    fn assert_has_english(block: &Block) {
        let en = block
            .en
            .as_ref()
            .unwrap_or_else(|| panic!("{} needs title_en", block.id));
        assert!(
            !en.title.is_empty() && !en.summary.is_empty() && !en.category.is_empty(),
            "{} needs title_en, summary_en and category_en",
            block.id
        );
    }

    #[test]
    fn categories_translate_consistently() {
        let mut seen: BTreeMap<String, String> = BTreeMap::new();
        for block in builtin().into_iter().chain(external(None)) {
            let en = block
                .en
                .as_ref()
                .map(|e| e.category.clone())
                .unwrap_or_default();
            let first = seen
                .entry(block.category.clone())
                .or_insert_with(|| en.clone());
            assert_eq!(*first, en, "{}: category {}", block.id, block.category);
        }
    }

    #[test]
    fn every_builtin_block_parses() {
        let blocks = builtin();
        assert_eq!(
            blocks.len(),
            BUILTIN.len(),
            "a built-in block has bad frontmatter"
        );
        for block in &blocks {
            assert!(
                !block.title.is_empty() && !block.summary.is_empty(),
                "{}",
                block.id
            );
            assert_has_english(block);
            assert!(
                !block.body.is_empty() && !block.body.starts_with("---"),
                "{}",
                block.id
            );
            assert!(
                crate::library::check_id(&block.name).is_ok(),
                "{}",
                block.id
            );
            if matches!(block.kind, BlockKind::Skill | BlockKind::Agent) {
                assert!(
                    block.description.is_some(),
                    "{} needs a description",
                    block.id
                );
                assert!(
                    block
                        .name
                        .chars()
                        .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-'),
                    "{}",
                    block.id
                );
            }
        }
        let ts = blocks
            .iter()
            .find(|b| b.id == "builtin:typescript")
            .unwrap();
        assert_eq!(ts.paths, ["**/*.ts", "**/*.tsx"]);
    }

    #[test]
    fn every_external_block_has_provenance_and_a_permissive_license() {
        let blocks = external(None);
        assert_eq!(
            blocks.len(),
            EXTERNAL.len(),
            "an external block lacks provenance"
        );
        for block in &blocks {
            let origin = block.origin.as_ref().unwrap();
            assert!(
                ["MIT", "Apache-2.0"].contains(&origin.license.as_str()),
                "{}",
                block.id
            );
            assert_eq!(
                origin.commit.len(),
                40,
                "{} must pin a full commit",
                block.id
            );
            assert!(block.description.is_some(), "{}", block.id);
            assert_has_english(block);
            assert!(!block.body.starts_with("---"), "{}", block.id);
            assert!(
                crate::library::check_id(&block.name).is_ok(),
                "{}",
                block.id
            );
        }
    }

    #[test]
    fn lists_keep_brace_globs_whole() {
        let value = "src/**/*.{ts,tsx}, lib/**, a/{b, c}/d".to_string();
        assert_eq!(
            list(Some(&value)),
            ["src/**/*.{ts,tsx}", "lib/**", "a/{b, c}/d"]
        );
    }

    #[test]
    fn crlf_and_bom_are_normalized() {
        let (fm, body) = split("\u{feff}---\r\nname: a\r\n---\r\n\r\nLine 1\r\nLine 2\r\n");
        assert_eq!(fm["name"], "a");
        assert_eq!(body, "Line 1\nLine 2\n");
        assert_eq!(
            raw_frontmatter("---\r\nname: a\r\nallowed-tools: Bash\r\n---\r\nBody").as_deref(),
            Some("name: a\nallowed-tools: Bash")
        );
    }

    #[test]
    fn split_returns_body_after_frontmatter() {
        let (fm, body) = split("---\nname: a\n---\n\n# Body\ntext\n");
        assert_eq!(fm["name"], "a");
        assert_eq!(body, "# Body\ntext\n");
        let (fm, body) = split("# No frontmatter\n");
        assert!(fm.is_empty());
        assert_eq!(body, "# No frontmatter\n");
    }

    #[test]
    fn library_items_become_blocks() {
        let tmp = tempfile::tempdir().unwrap();
        let skill = tmp.path().join("skills").join("deploy");
        std::fs::create_dir_all(skill.join("scripts")).unwrap();
        std::fs::write(
            skill.join("SKILL.md"),
            "---\nname: deploy\ndescription: Ship it\n---\nSteps\n",
        )
        .unwrap();
        std::fs::write(skill.join("scripts").join("run.sh"), "echo").unwrap();
        let item = LibraryItem {
            kind: ItemKind::Skill,
            id: "deploy".into(),
            name: "deploy".into(),
            description: Some("Ship it".into()),
            path: skill.join("SKILL.md").display().to_string(),
            mode: None,
            status: None,
        };
        let block = from_library(&item).unwrap();
        assert_eq!(block.id, "library:skill:deploy");
        assert_eq!(block.body, "Steps");
        assert_eq!(block.extra_files, 1);
        assert_eq!(
            block.frontmatter.as_deref(),
            Some("name: deploy\ndescription: Ship it")
        );
    }

    #[test]
    fn long_descriptions_shorten_to_their_first_sentence() {
        assert_eq!(
            first_sentence("Reviews code. Use after every change.\nMore."),
            "Reviews code."
        );
        assert_eq!(
            first_sentence("Use v1.2 tools for x"),
            "Use v1.2 tools for x"
        );
        assert_eq!(first_sentence("Line one\nline two"), "Line one");
    }

    #[test]
    fn bundled_blocks_carry_a_detail_in_both_languages() {
        for block in builtin().into_iter().chain(external(None)) {
            assert!(
                block.detail.as_deref().is_some_and(|d| d.len() > 20),
                "{}",
                block.id
            );
            let en = block.en.as_ref().unwrap();
            assert!(
                en.detail.as_deref().is_some_and(|d| d.len() > 20),
                "{}",
                block.id
            );
            assert!(
                block.summary.chars().count() <= 40,
                "{}: {}",
                block.id,
                block.summary
            );
        }
    }
}
